python3 << 'EOF'
import subprocess
import json
import urllib.parse
from datetime import datetime, timedelta

# Now let's try to get pageviews data for the articles we found
# Using the Wikipedia API's pageviews property

articles = [
    {
        'wiki': 'pl.wikipedia.org',
        'title': 'Głodówka lecznicza',
        'description': 'Polish - Therapeutic Fasting'
    },
    {
        'wiki': 'cs.wikipedia.org',
        'title': 'Přerušovaný půst',
        'description': 'Czech - Intermittent Fasting'
    },
    {
        'wiki': 'en.wikipedia.org',
        'title': 'Intermittent fasting',
        'description': 'English - Intermittent Fasting'
    }
]

print("Fetching pageviews data for the last 60 days from Wikipedia API...\n")

all_data = {}

for article in articles:
    url = f"https://{article['wiki']}/w/api.php"
    params = {
        'action': 'query',
        'titles': article['title'],
        'prop': 'pageviews',
        'pvipdays': '100',  # Get last 100 days
        'format': 'json'
    }

    query_string = urllib.parse.urlencode(params)
    full_url = f"{url}?{query_string}"

    print(f"Fetching: {article['description']}")
    result = subprocess.run(['curl', '-s', full_url], capture_output=True, text=True, timeout=10)

    try:
        data = json.loads(result.stdout)
        if 'query' in data and 'pages' in data['query']:
            for page_id, page_data in data['query']['pages'].items():
                if 'pageviews' in page_data:
                    pageviews = page_data['pageviews']
                    # Filter out None values and convert to sorted list
                    views_list = [(date, views) for date, views in sorted(pageviews.items()) if views is not None]
                    all_data[article['description']] = views_list

                    if views_list:
                        print(f"  Found {len(views_list)} days of data")
                        print(f"  Latest data: {views_list[-5:]}")
                    else:
                        print(f"  No data available")
                else:
                    print(f"  No pageviews data available")
        else:
            print(f"  Error: Could not query page")
    except json.JSONDecodeError as e:
        print(f"  Error parsing JSON: {e}")
        print(f"  Response: {result.stdout[:200]}")

# Save the data for later analysis
import pickle
with open('/tmp/pageviews_data.pkl', 'wb') as f:
    pickle.dump(all_data, f)

print("\nData saved for analysis")

